function findOrder(numCourses, prerequisites) {
  const unlocks = [];                       // unlocks[p] = courses that list p as a prerequisite
  const needs = new Array(numCourses).fill(0);  // in-degree: prerequisites not yet taken
  for (let course = 0; course < numCourses; course++) unlocks.push([]);
  for (const [course, prerequisite] of prerequisites) {
    unlocks[prerequisite].push(course);
    needs[course] += 1;
  }

  const queue = [];
  for (let course = 0; course < numCourses; course++) {
    if (needs[course] === 0) queue.push(course);
  }

  const order = [];
  let head = 0;
  while (head < queue.length) {
    const course = queue[head];
    head += 1;
    order.push(course);
    for (const next of unlocks[course]) {
      needs[next] -= 1;
      if (needs[next] === 0) queue.push(next);
    }
  }
  return order.length === numCourses ? order : [];   // leftovers mean a cycle
}

