function isValid(n, pre, order) {
  if (order.length !== n || new Set(order).size !== n) return false;
  const pos = new Map(order.map((c, i) => [c, i]));
  return pre.every(([c, p]) => pos.has(c) && pos.has(p) && pos.get(p) < pos.get(c));
}
const pre = [[1,0],[2,0],[3,1],[3,2]];
const order = findOrder(4, pre);
assert(isValid(4, pre, order), 'not a valid order: ' + JSON.stringify(order));

